import { describe, expect, it } from 'vitest'
import {
  credentialsManifestExists,
  guardNotProduction,
  loadCredentials,
} from './auth-harness'

describe('11-2 AC3 — guardNotProduction is the belt tripwire (prod/dev PAIR)', () => {
  // The PAIR is what kills the throw-stub false-green: a prod target must throw,
  // AND a dev target must NOT throw. The dev-proceeds case is red first against
  // the throw-stub — that is the load-bearing red assertion for this gate.
  it('throws when the target host is production-shaped (outside the allowlist)', () => {
    expect(() =>
      guardNotProduction({ baseURL: 'https://my.classlite.app' }),
    ).toThrow()
  })

  it('does NOT throw for a development target (dashboard localhost)', () => {
    expect(() =>
      guardNotProduction({ baseURL: 'http://my.classlite.localhost:5173' }),
    ).not.toThrow()
  })

  it('does NOT throw for the cross-subdomain localhost host', () => {
    expect(() =>
      guardNotProduction({ baseURL: 'http://classlite.localhost:4321' }),
    ).not.toThrow()
  })
})

describe('11-2 AC1 — credentials manifest contract (consumed from 11-1a)', () => {
  // The manifest is a DB-dependent, gitignored seed OUTPUT (DD3): present in a
  // seeded local/E2E environment, absent in the web unit-CI (no DB). Skip-with-
  // reason when absent (same idiom as the COOKIE_DOMAIN precondition on
  // cookie-sharing.spec.ts) so the gate is green everywhere; assert fully when
  // present so the seeded run enforces the contract. The AC3 guard tests above
  // are pure-logic and always run — the WF-8 teeth are never skipped.
  it.skipIf(!credentialsManifestExists())(
    'loadCredentials returns an array of {role,email,password,centerShortCode,centerId}',
    () => {
      const creds = loadCredentials()
      expect(Array.isArray(creds)).toBe(true)
      // 11-1a emits one row per seeded creds-role per tenant. The harness only
      // LOGS IN the consumed subset (teacher + teacher2, tenant A) — AC6 — but
      // the manifest must still contain both teacher identities to pick from.
      const emails = creds.map((c) => c.email)
      const teachers = creds.filter((c) => c.role === 'teacher')
      expect(teachers.length).toBeGreaterThanOrEqual(2) // teacher + teacher2 (D1)
      for (const c of creds) {
        expect(c.email).toBeTruthy()
        expect(c.password).toBeTruthy()
        expect(c.centerId).toBeTruthy()
        expect(c.centerShortCode).toBeTruthy()
      }
      expect(new Set(emails).size).toBe(emails.length) // no dup identities
    },
  )
})
